192	const arrowDidUpdate = (editor: Editor, arrow: DiscourseRelationShape) => {
193	  const bindings = getArrowBindings(editor, arrow);
194	  // if the shape is an arrow and its bound shape is on another page
195	  // or was deleted, unbind it
196	  for (const handle of ["start", "end"] as const) {
197	    const binding = bindings[handle];
198	    if (!binding) continue;
199	    const boundShape = editor.getShape(binding.toId);
200	    if (!boundShape) {
201	      updateArrowTerminal({ editor, arrow, terminal: handle, unbind: true });
202	      continue;
203	    }
204	    const isShapeInSamePageAsArrow =
205	      editor.getAncestorPageId(arrow) === editor.getAncestorPageId(boundShape);
206	    if (!isShapeInSamePageAsArrow) {
207	      updateArrowTerminal({ editor, arrow, terminal: handle, unbind: true });
208	    }
209	  }
210	
211	  // always check the arrow parents
212	  reparentArrow(editor, arrow.id);
213	};
