215	const reparentArrow = (editor: Editor, arrowId: TLShapeId) => {
216	  const arrow = editor.getShape<DiscourseRelationShape>(arrowId);
217	  if (!arrow) return;
218	  const bindings = getArrowBindings(editor, arrow);
219	  const { start, end } = bindings;
220	  const startShape = start ? editor.getShape(start.toId) : undefined;
221	  const endShape = end ? editor.getShape(end.toId) : undefined;
222	
223	  const parentPageId = editor.getAncestorPageId(arrow);
224	  if (!parentPageId) return;
225	
226	  let nextParentId: TLParentId;
227	  if (startShape && endShape) {
228	    // if arrow has two bindings, always parent arrow to closest common ancestor of the bindings
229	    nextParentId =
230	      editor.findCommonAncestor([startShape, endShape]) ?? parentPageId;
231	  } else if (startShape || endShape) {
232	    const bindingParentId = (startShape || endShape)?.parentId;
233	    // If the arrow and the shape that it is bound to have the same parent, then keep that parent
234	    if (bindingParentId && bindingParentId === arrow.parentId) {
235	      nextParentId = arrow.parentId;
236	    } else {
237	      // if arrow has one binding, keep arrow on its own page
238	      nextParentId = parentPageId;
239	    }
240	  } else {
241	    return;
242	  }
243	
244	  if (nextParentId && nextParentId !== arrow.parentId) {
245	    editor.reparentShapes([arrowId], nextParentId);
246	  }
247	
248	  const reparentedArrow = editor.getShape<DiscourseRelationShape>(arrowId);
249	  if (!reparentedArrow) throw Error("no reparented arrow");
250	
251	  const startSibling = getShapeNearestSibling(
252	    editor,
253	    reparentedArrow,
254	    startShape,
255	  );
256	  const endSibling = getShapeNearestSibling(editor, reparentedArrow, endShape);
257	
258	  let highestSibling: TLShape | undefined;
259	
260	  if (startSibling && endSibling) {
261	    highestSibling =
262	      startSibling.index > endSibling.index ? startSibling : endSibling;
263	  } else if (startSibling && !endSibling) {
264	    highestSibling = startSibling;
265	  } else if (endSibling && !startSibling) {
266	    highestSibling = endSibling;
267	  } else {
268	    return;
269	  }
270	
271	  let finalIndex: IndexKey;
272	
273	  const higherSiblings = editor
274	    .getSortedChildIdsForParent(highestSibling.parentId)
275	    .map((id) => editor.getShape(id)!)
276	    .filter((sibling) => sibling.index > highestSibling.index);
277	
278	  if (higherSiblings.length) {
279	    // there are siblings above the highest bound sibling, we need to
280	    // insert between them.
281	
282	    // if the next sibling is also a bound arrow though, we can end up
283	    // all fighting for the same indexes. so lets find the next
284	    // non-arrow sibling...
285	    const nextHighestNonArrowSibling = higherSiblings.find(
286	      (sibling) => sibling.type !== arrow.type,
287	    );
288	
289	    if (
290	      // ...then, if we're above the last shape we want to be above...
291	      reparentedArrow.index > highestSibling.index &&
292	      // ...but below the next non-arrow sibling...
293	      (!nextHighestNonArrowSibling ||
294	        reparentedArrow.index < nextHighestNonArrowSibling.index)
295	    ) {
296	      // ...then we're already in the right place. no need to update!
297	      return;
298	    }
299	
300	    // otherwise, we need to find the index between the highest sibling
301	    // we want to be above, and the next highest sibling we want to be
302	    // below:
303	    finalIndex = getIndexBetween(
304	      highestSibling.index,
305	      higherSiblings[0]?.index,
306	    );
307	  } else {
308	    // if there are no siblings above us, we can just get the next index:
309	    finalIndex = getIndexAbove(highestSibling.index);
310	  }
311	
312	  if (finalIndex !== reparentedArrow.index) {
313	    editor.updateShapes<DiscourseRelationShape>([
314	      { id: arrowId, type: arrow.type, index: finalIndex },
315	    ]);
316	  }
317	};
