319	const getShapeNearestSibling = (
320	  editor: Editor,
321	  siblingShape: TLShape,
322	  targetShape: TLShape | undefined,
323	): TLShape | undefined => {
324	  if (!targetShape) {
325	    return undefined;
326	  }
327	  if (targetShape.parentId === siblingShape.parentId) {
328	    return targetShape;
329	  }
330	
331	  const ancestor = editor.findShapeAncestor(
332	    targetShape,
333	    (ancestor) => ancestor.parentId === siblingShape.parentId,
334	  );
335	
336	  return ancestor;
337	};
