339	export const updateArrowTerminal = ({
340	  editor,
341	  arrow,
342	  terminal,
343	  unbind = false,
344	  useHandle = false,
345	}: {
346	  editor: Editor;
347	  arrow: DiscourseRelationShape;
348	  terminal: "start" | "end";
349	  unbind?: boolean;
350	  useHandle?: boolean;
351	}) => {
352	  const info = getArrowInfo(editor, arrow);
353	  if (!info) {
354	    throw new Error("expected arrow info");
355	  }
356	
357	  const startPoint = useHandle ? info.start.handle : info.start.point;
358	  const endPoint = useHandle ? info.end.handle : info.end.point;
359	  const point = terminal === "start" ? startPoint : endPoint;
360	
361	  const update = {
362	    id: arrow.id,
363	    type: arrow.type,
364	    props: { [terminal]: { x: point.x, y: point.y }, bend: arrow.props.bend },
365	  } satisfies TLShapePartial<DiscourseRelationShape>;
366	
367	  // fix up the bend:
368	  if (!info.isStraight) {
369	    // find the new start/end points of the resulting arrow
370	    const newStart = terminal === "start" ? startPoint : info.start.handle;
371	    const newEnd = terminal === "end" ? endPoint : info.end.handle;
372	    const newMidPoint = Vec.Med(newStart, newEnd);
373	
374	    // intersect a line segment perpendicular to the new arrow with the old arrow arc to
375	    // find the new mid-point
376	    const lineSegment = Vec.Sub(newStart, newEnd)
377	      .per()
378	      .uni()
379	      .mul(info.handleArc.radius * 2 * Math.sign(arrow.props.bend));
380	
381	    // find the intersections with the old arrow arc:
382	    const intersections = intersectLineSegmentCircle(
383	      info.handleArc.center,
384	      Vec.Add(newMidPoint, lineSegment),
385	      info.handleArc.center,
386	      info.handleArc.radius,
387	    );
388	
389	    assert(intersections?.length === 1);
390	    const bend =
391	      Vec.Dist(newMidPoint, intersections[0]!) * Math.sign(arrow.props.bend);
392	    // use `approximately` to avoid endless update loops
393	    if (!approximately(bend, update.props.bend)) {
394	      update.props.bend = bend;
395	    }
396	  }
397	
398	  editor.updateShape(update);
399	  if (unbind) {
400	    removeArrowBinding(editor, arrow, terminal);
401	  }
402	};
