404	const intersectLineSegmentCircle = (
405	  a1: VecLike,
406	  a2: VecLike,
407	  c: VecLike,
408	  r: number,
409	  // eslint-disable-next-line max-params -- mirrors tldraw's intersectLineSegmentCircle signature
410	) => {
411	  const a = (a2.x - a1.x) * (a2.x - a1.x) + (a2.y - a1.y) * (a2.y - a1.y);
