                disabled={isReadonly}
                onSelect={() => {
                  void convertArrowToDiscourseRelation({
                    editor,
                    plugin,
                    canvasFile,
                    arrowId: selectedShape.id,
                    relationTypeId: relationType.id,
                  });
                }}
              />
            ))}
          </TldrawUiMenuSubmenu>
        </TldrawUiMenuGroup>
      )}
      {shouldShowConvertTo && selectedShape && (
        <TldrawUiMenuGroup id="convert-to">
          <TldrawUiMenuSubmenu id="convert-to-submenu" label="Convert To">
            {plugin.settings.nodeTypes.map((nodeType) => (
              <TldrawUiMenuItem
                key={nodeType.id}
                id={`convert-to-${nodeType.id}`}
                label={nodeType.name}
                icon="file-type"
                disabled={isReadonly}
                onSelect={() => {
                  void convertToDiscourseNode({
                    editor,
                    shape: selectedShape,
                    nodeType,
                    plugin,
                    canvasFile,
                  });
                }}
              />
            ))}
          </TldrawUiMenuSubmenu>
        </TldrawUiMenuGroup>
      )}
    </DefaultContextMenu>
  );
};
